<script setup lang="ts">import {reactive,watch} from 'vue';const props=defineProps<{modelValue?:Record<string,unknown>|null}>();const emit=defineEmits<{save:[value:Record<string,unknown>];cancel:[]}>();const form=reactive({name:'',type:'',level:'',contactName:'',contactPhone:'',address:'',description:''});watch(()=>props.modelValue,v=>Object.assign(form,{name:'',type:'',level:'',contactName:'',contactPhone:'',address:'',description:'',...(v||{})}),{immediate:true});</script>
<template><form class="work-item-form" @submit.prevent="emit('save',{...form})"><label>客户名称<input v-model="form.name" required placeholder="请输入客户名称"/></label><div class="form-grid"><label>客户类型<input v-model="form.type" placeholder="请输入客户类型"/></label><label>客户等级<input v-model="form.level" placeholder="请输入客户等级"/></label></div><div class="form-grid"><label>联系人<input v-model="form.contactName" placeholder="请输入联系人"/></label><label>联系电话<input v-model="form.contactPhone" placeholder="请输入联系电话"/></label></div><label>地址<input v-model="form.address" placeholder="请输入地址"/></label><label>备注<textarea v-model="form.description" rows="3" placeholder="请输入备注"/></label><div class="form-actions"><button type="button" class="secondary" @click="emit('cancel')">取消</button><button class="primary">保存</button></div></form></template>
